//! Offline sealed-baseline/candidate public API probe. Build/link is owned by the runner.
//! Usage: window_probe CASE RECEIPT.json; fixed 6000 seed bars and 9 samples per forming path.
include!("window_probe_common.rs");

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let arguments: Vec<_> = std::env::args().collect();
    if arguments.len() != 3 || !CASES.contains(&arguments[1].as_str()) {
        return Err(format!("usage: window_probe CASE RECEIPT.json; CASE in {CASES:?}").into());
    }
    let case = arguments[1].as_str();
    let supplied = PathBuf::from(&arguments[2]);
    let receipt = if supplied.is_absolute() { supplied } else { std::env::current_dir()?.join(supplied) };
    if let Some(parent) = receipt.parent() { std::fs::create_dir_all(parent)?; }
    let parts = receipt.with_extension("parts");
    std::fs::create_dir_all(&parts)?;
    let source_text = script(case);
    let source = SourceFile::new("window_probe.pine", source_text.clone());
    let prices: Vec<_> = (0..BARS).map(|index| close(case, index)).collect();
    let bars: Vec<_> = prices.iter().enumerate().map(|(index, &price)| bar(index, price)).collect();
    let (oracle_model, expected_seed) = oracle_seed(case, &prices);
    let mut files = Vec::new();
    let mut typed_files = Vec::new();
    let (analysis, analyze_metric) = measure(|| analyze_source(&source));
    if analysis.diagnostics.iter().any(|diagnostic| diagnostic.severity == Severity::Error) {
        return Err(format!("analysis failed: {:?}", analysis.diagnostics).into());
    }
    let hir = analysis.hir.ok_or("missing executable HIR")?;
    let (prepared, prepared_metric) = measure(|| PreparedProgram::new(hir));

    // Session construction, all encoders, oracle reads and caller drops are outside these windows.
    let mut historical = HistoricalRuntime::from_prepared(&prepared);
    let (historical_output, historical_metric) = measure(|| {
        historical.append_bars(&bars)?;
        Ok::<RuntimeResult, RuntimeError>(historical.result())
    });
    let historical_output = historical_output.map_err(|error| error.message)?;
    let historical_check = check_result(&historical_output, &expected_seed)?;
    check_profile(&historical.profile(), case, BARS)?;
    let historical_profile = profile_json(&historical.profile())?;
    let seed_json = public_runtime_result_json(&historical_output);
    save_payload(&parts, "historical-owned", "runtimeResult", &seed_json, &mut files)?;
    save_typed(&parts, "historical-owned-typed", &historical_output, &mut typed_files)?;
    drop(historical_output);
    drop(historical);

    let mut realtime = RealtimeRuntime::from_prepared(&prepared);
    let (seeded, realtime_seed_metric) = measure(|| realtime.seed_historical_without_output(&bars));
    seeded.map_err(|error| error.message)?;
    check_profile(&realtime.profile(), case, BARS)?;
    let confirmed_profile = realtime.confirmed_profile();
    let seed_output = realtime.result();
    check_result(&seed_output, &expected_seed)?;
    let realtime_seed_json = public_runtime_result_json(&seed_output);
    if realtime_seed_json != seed_json { return Err("historical/stream seed complete public outputs differ".into()); }
    save_payload(&parts, "stream-seed", "runtimeResult", &realtime_seed_json, &mut files)?;
    save_typed(&parts, "stream-seed-typed", &seed_output, &mut typed_files)?;
    drop(seed_output);
    drop(realtime_seed_json);
    drop(seed_json);
    let seeded_revision = realtime.revision();
    let mut without_samples = Vec::with_capacity(SAMPLES);
    let mut borrowed_samples = Vec::with_capacity(SAMPLES);
    let mut checks = Vec::with_capacity(SAMPLES * 2 + 2);
    for sample in 0..SAMPLES {
        let price = forming_price(case, sample, false);
        let (updated, metric) = measure(|| realtime.update_without_output(BarUpdate::forming(bar(BARS, price))));
        updated.map_err(|error| error.message)?;
        if realtime.confirmed_bar_count() != BARS || realtime.confirmed_profile() != confirmed_profile
            || realtime.last_changes().is_some() || realtime.revision() != seeded_revision + sample as u64 + 1 {
            return Err("forming without-output changed committed state or cursor contract".into());
        }
        let output = realtime.result();
        let checked = check_result(&output, &oracle_forming(&oracle_model, &expected_seed, price))?;
        check_profile(&realtime.profile(), case, BARS + 1)?;
        save_payload(&parts, &format!("without-output-{sample}"), "runtimeResult", &public_runtime_result_json(&output), &mut files)?;
        save_typed(&parts, &format!("without-output-{sample}-typed"), &output, &mut typed_files)?;
        checks.push(json!({"phase": "formingWithoutOutput", "sample": sample, "price": price,
            "revision": realtime.revision(), "oracle": checked, "profile": profile_json(&realtime.profile())?}));
        without_samples.push(metric);
    }

    // Resetting a replica after the no-delta path is part of consumer setup, outside timing.
    let mut replica = realtime.replica();
    for sample in 0..SAMPLES {
        let price = forming_price(case, sample, true);
        let (metric, delta_json) = {
            let measurement = Measurement::begin();
            let changes = realtime.apply_update_ref(BarUpdate::forming(bar(BARS, price))).map_err(|error| error.message)?;
            let metric = measurement.finish();
            if changes.visibility != StreamingVisibility::Preview || !replica.apply(changes).map_err(|error| error.message)? {
                return Err("borrowed forming delta was not applied as a new preview revision".into());
            }
            // These operations use the actual borrowed delta; no clone or replica work is measured.
            (metric, public_runtime_changes_json(changes))
        };
        let output = realtime.result();
        let checked = check_result(&output, &oracle_forming(&oracle_model, &expected_seed, price))?;
        check_profile(&realtime.profile(), case, BARS + 1)?;
        if realtime.confirmed_bar_count() != BARS || realtime.confirmed_profile() != confirmed_profile
            || replica.revision() != realtime.revision() || replica.result() != &output
            || realtime.revision() != seeded_revision + (SAMPLES + sample + 1) as u64 {
            return Err("borrowed delta/replica producer state diverged".into());
        }
        save_payload(&parts, &format!("borrowed-delta-{sample}"), "runtimeChanges", &delta_json, &mut files)?;
        save_payload(&parts, &format!("borrowed-output-{sample}"), "runtimeResult", &public_runtime_result_json(&output), &mut files)?;
        save_typed(&parts, &format!("borrowed-output-{sample}-typed"), &output, &mut typed_files)?;
        checks.push(json!({"phase": "formingBorrowedDelta", "sample": sample, "price": price,
            "revision": realtime.revision(), "replicaMatchesFullResult": true, "oracle": checked,
            "profile": profile_json(&realtime.profile())?}));
        borrowed_samples.push(metric);
    }

    // Untimed changed-input transitions invalidate a constant certificate and
    // prove future rolling state after both kinds of repeated forming updates.
    let [confirmed_price, next_price] = future_prices(case);
    let mut final_model = oracle_model.clone();
    let mut final_expected = expected_seed.clone();
    for (name, index, price, update) in [
        ("confirmed", BARS, confirmed_price, BarUpdate::confirmed(bar(BARS, confirmed_price))),
        ("next-historical", BARS + 1, next_price, BarUpdate::historical(bar(BARS + 1, next_price))),
    ] {
        let delta_json = {
            let changes = realtime.apply_update_ref(update).map_err(|error| error.message)?;
            if changes.visibility != StreamingVisibility::Confirmed || !replica.apply(changes).map_err(|error| error.message)? {
                return Err("future committed delta was not applied".into());
            }
            public_runtime_changes_json(changes)
        };
        append_expected(&mut final_expected, final_model.advance(index, price));
        let output = realtime.result();
        let checked = check_result(&output, &final_expected)?;
        check_profile(&realtime.profile(), case, index + 1)?;
        if realtime.confirmed_bar_count() != index + 1 || realtime.profile() != realtime.confirmed_profile()
            || replica.revision() != realtime.revision() || replica.result() != &output {
            return Err("future committed output or replica diverged".into());
        }
        save_payload(&parts, &format!("{name}-delta"), "runtimeChanges", &delta_json, &mut files)?;
        save_payload(&parts, &format!("{name}-output"), "runtimeResult", &public_runtime_result_json(&output), &mut files)?;
        save_typed(&parts, &format!("{name}-output-typed"), &output, &mut typed_files)?;
        checks.push(json!({"phase": name, "measured": false, "price": price,
            "revision": realtime.revision(), "replicaMatchesFullResult": true, "oracle": checked,
            "profile": profile_json(&realtime.profile())?}));
    }
    let result = json!({
        "probe": "publicWindowCertificates", "probeVersion": 1, "case": case,
        "bars": BARS, "samplesPerFormingStage": SAMPLES, "pineSource": source_text,
        "stages": {"analyze": analyze_metric, "prepared": prepared_metric,
            "historicalFullOutput": historical_metric, "streamSeedWithoutOutput": realtime_seed_metric,
            "formingWithoutOutput": without_samples, "formingBorrowedDelta": borrowed_samples},
        "historicalOracle": historical_check, "historicalProfile": historical_profile,
        "streamSeedProfile": profile_json(&confirmed_profile)?, "checks": checks,
        "seededRevision": seeded_revision, "finalRevision": realtime.revision(),
        "rawPayloadFiles": files, "rawTypedValueFiles": typed_files, "strictBeforeAfterPayloadDifferencesAllowed": [],
        "windowLength": LENGTH, "plotCount": plot_count(case), "rollingWindowCount": window_count(case),
        "measurementScope": "one public analyze/prepared/seed/update call per window; historicalFullOutput includes append_bars plus owned result(); session setup, caller disposal, full public serialization, mathematical/seeded oracle, profile reads, replica construction/apply and receipt IO are outside windows",
        "allocatorScope": "System layout-request accounting of successful allocation/zeroed allocation/reallocation; realloc removes old live size and adds new size once; peak above stage-entry requested live bytes and signed exit live delta; not process RSS or allocator residency",
        "semanticScope": "complete typed oracle for every snapshot, 33 full public JSON payloads and 22 full typed-plot sidecars for byte/SHA256 before-after comparison, exact producer/RuntimeReplica equality after every borrowed delta, unchanged confirmed profile during forming, untimed changed-input confirm and next historical transitions",
        "fixtureScope": "6000 bars; 3000-window dyadic constant 100.25 WMA/HMA and variance; decimal 0.1 fallback; dyadic varying control; 1e308 sum warming and ready overflow; dynamic 3000/1536 lengths with two NA inputs; same-callsite four-iteration sum/SMA loop; existing zero fast-path control. Constant fixtures keep the input unchanged during timed forming stages, then change it in untimed future checks.",
        "limitations": "offline native indicator cases only; before/after equality preserves the sealed runtime's numerical contract and does not establish TradingView parity; requested allocation accounting and instrumented latency are not process RSS, host/strategy/request performance, full resource-matrix or release qualification",
    });
    std::fs::write(&receipt, serde_json::to_string(&result)?)?;
    println!("{}", json!({"receipt": receipt.to_string_lossy(), "case": case, "bars": BARS,
        "samplesPerFormingStage": SAMPLES, "rawPayloadCount": result["rawPayloadFiles"].as_array().unwrap().len(),
        "rawTypedValueCount": result["rawTypedValueFiles"].as_array().unwrap().len()}));
    Ok(())
}

