// This include and window_probe.rs must be byte-identical in both linked binaries.
// Only baseline public Rust APIs are used. No private runtime field or dispatch kernel is timed.
use pine_runtime::*;
use pine_sema::analyze_source;
use pine_syntax::{Severity, SourceFile};
use serde_json::{Value, json};
use std::alloc::{GlobalAlloc, Layout, System};
use std::hint::black_box;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
use std::time::Instant;

const BARS: usize = 6_000;
const SAMPLES: usize = 9;
const CASES: [&str; 8] = [
    "dyadic_wma_hma", "variance_exact_zero", "decimal_fallback", "varying_control",
    "cold_sum_warming", "dynamic_na", "same_callsite_loop", "zero_control",
];
const LENGTH: usize = 3_000;

struct CountingAllocator;
static LIVE: AtomicUsize = AtomicUsize::new(0);
static PEAK: AtomicUsize = AtomicUsize::new(0);
static ALLOCATED: AtomicUsize = AtomicUsize::new(0);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
fn allocation(size: usize) {
    ALLOCATED.fetch_add(size, Relaxed);
    ALLOCS.fetch_add(1, Relaxed);
    let live = LIVE.fetch_add(size, Relaxed) + size;
    PEAK.fetch_max(live, Relaxed);
}
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let result = unsafe { System.alloc(layout) };
        if !result.is_null() { allocation(layout.size()); }
        result
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        let result = unsafe { System.alloc_zeroed(layout) };
        if !result.is_null() { allocation(layout.size()); }
        result
    }
    unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Relaxed);
        unsafe { System.dealloc(pointer, layout) }
    }
    unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        let result = unsafe { System.realloc(pointer, layout, size) };
        if !result.is_null() {
            LIVE.fetch_sub(layout.size(), Relaxed);
            allocation(size);
        }
        result
    }
}
#[global_allocator]
static GLOBAL: CountingAllocator = CountingAllocator;

struct Measurement {
    initial: usize,
    bytes: usize,
    count: usize,
    started: Instant,
}
impl Measurement {
    fn begin() -> Self {
        let initial = LIVE.load(Relaxed);
        PEAK.store(initial, Relaxed);
        Self {
            initial,
            bytes: ALLOCATED.load(Relaxed),
            count: ALLOCS.load(Relaxed),
            started: Instant::now(),
        }
    }
    fn finish(self) -> Value {
        let ms = self.started.elapsed().as_secs_f64() * 1000.0;
        let bytes = ALLOCATED.load(Relaxed) - self.bytes;
        let count = ALLOCS.load(Relaxed) - self.count;
        let peak = PEAK.load(Relaxed).saturating_sub(self.initial);
        let live_delta = LIVE.load(Relaxed) as i64 - self.initial as i64;
        // All counter reads finish before JSON construction allocates.
        json!({"ms": ms, "allocatedBytes": bytes, "allocations": count,
            "peakAdditionalLiveBytes": peak, "liveDeltaBytes": live_delta})
    }
}
fn measure<T>(operation: impl FnOnce() -> T) -> (T, Value) {
    let measurement = Measurement::begin();
    let result = black_box(operation());
    (result, measurement.finish())
}

fn close(case: &str, index: usize) -> f64 {
    match case {
        "decimal_fallback" => 0.1,
        "cold_sum_warming" => 1.0e308,
        "zero_control" => 0.0,
        "varying_control" | "dynamic_na" => 100.0 + ((index * 17) % 257) as f64 / 4.0,
        _ => 100.25,
    }
}
fn forming_price(case: &str, sample: usize, borrowed: bool) -> f64 {
    let base = close(case, BARS);
    if matches!(case, "varying_control" | "dynamic_na") {
        base + (if borrowed { -1.0 } else { 1.0 }) * (sample + 1) as f64 * 0.25
    } else { base }
}
fn future_prices(case: &str) -> [f64; 2] {
    match case {
        "cold_sum_warming" => [7.5e307, 5.0e307],
        "decimal_fallback" => [0.2, 0.3],
        "zero_control" => [0.25, 0.5],
        _ => [close(case, BARS) + 0.25, close(case, BARS + 1) + 0.5],
    }
}
fn bar(index: usize, price: f64) -> Bar {
    Bar { time: 1_700_000_000_000 + index as i64 * 60_000,
        open: price - 0.5, high: price + 1.0, low: price - 1.0,
        close: price, volume: 100.0 + (index % 31) as f64 }
}
fn plot_count(case: &str) -> usize {
    match case { "dyadic_wma_hma" | "same_callsite_loop" => 2,
        "variance_exact_zero" => 4, "cold_sum_warming" => 1, "dynamic_na" => 5, _ => 3 }
}
fn window_count(case: &str) -> usize {
    match case { "dyadic_wma_hma" => 3, "same_callsite_loop" => 2,
        "cold_sum_warming" => 1, "dynamic_na" => 6, _ => 4 }
}
fn script(case: &str) -> String {
    let mut source = String::from("//@version=6\nindicator(\"window certificates public API\")\n");
    match case {
        "dyadic_wma_hma" => source.push_str("plot(ta.wma(close, 3000))\nplot(ta.hma(close, 3000))\n"),
        "variance_exact_zero" => source.push_str("plot(ta.variance(close, 3000, true))\nplot(ta.variance(close, 3000, false))\nplot(ta.stdev(close, 3000, true))\nplot(ta.stdev(close, 3000, false))\n"),
        "decimal_fallback" | "varying_control" | "zero_control" => source.push_str("plot(ta.wma(close, 3000))\nplot(ta.hma(close, 3000))\nplot(ta.variance(close, 3000))\n"),
        "cold_sum_warming" => source.push_str("plot(math.sum(close, 3000))\n"),
        "dynamic_na" => source.push_str("source = (bar_index == 3100 or bar_index == 3101) ? na : close\nlength = bar_index % 211 < 106 ? 3000 : 1536\nplot(ta.wma(source, length))\nplot(ta.hma(source, length))\nplot(ta.variance(source, length))\nplot(ta.sma(source, length))\nplot(math.sum(source, length))\n"),
        "same_callsite_loop" => source.push_str("float total = na\nfloat average = na\nfor i = 0 to 3\n    total := math.sum(close + i * 0.25, 3000)\n    average := ta.sma(close + i * 0.25, 3000)\nplot(total)\nplot(average)\n"),
        _ => unreachable!("validated case"),
    }
    source
}

// Independent public-output oracle with ordinary VecDeque storage. It never calls a
// runtime helper. Bounded WMA/HMA inputs need only the original sequential formula;
// decimal variance intentionally preserves the old rolling mean's floating bits.
// All oracle construction, scans and cloning are outside measurement windows.
#[derive(Clone, Default)]
struct OracleWindow {
    values: std::collections::VecDeque<Option<f64>>,
    sum: f64,
    na_count: usize,
    nonzero_count: usize,
}
impl OracleWindow {
    fn push(&mut self, value: Option<f64>, length: usize, per_bar: bool) {
        let previous_sum = self.sum;
        let mut evicted = Vec::new();
        while self.values.len() >= length {
            let value = self.values.pop_front().unwrap();
            if let Some(value) = value {
                self.sum -= value;
                self.nonzero_count -= usize::from(value != 0.0);
            } else { self.na_count -= 1; }
            if self.nonzero_count == 0 && self.na_count == 0 { self.sum = 0.0; }
            evicted.push(value);
        }
        if let Some(value) = value {
            self.sum += value;
            self.nonzero_count += usize::from(value != 0.0);
        } else { self.na_count += 1; }
        self.values.push_back(value);
        if per_bar && evicted.len() == 1
            && let (Some(incoming), Some(outgoing)) = (value, evicted[0])
            && incoming.is_sign_positive() == outgoing.is_sign_positive()
            && incoming.abs() >= outgoing.abs() * 0.5
            && outgoing.abs() >= incoming.abs() * 0.5 {
            self.sum = previous_sum + (incoming - outgoing);
        }
        if self.nonzero_count == 0 && self.na_count == 0 { self.sum = 0.0; }
    }
    fn ready(&self, length: usize) -> bool { self.values.len() == length && self.na_count == 0 }
    fn weighted(&self, length: usize, start: usize) -> f64 {
        let weighted_sum = self.values.iter().skip(start).flatten().enumerate()
            .map(|(index, value)| *value * (index + 1) as f64).sum::<f64>();
        let length = length - start;
        weighted_sum / (length * (length + 1) / 2) as f64
    }
    fn variance(&self, length: usize, biased: bool) -> f64 {
        let mean = self.sum / length as f64;
        let residual = self.values.iter().flatten().map(|value| {
            let difference = *value - mean;
            difference * difference
        }).sum::<f64>();
        let denominator = if biased { length } else { length - 1 };
        (residual / denominator as f64).max(0.0)
    }
}
#[derive(Clone, Default)]
struct OracleHull { full: OracleWindow, smooth: OracleWindow }
impl OracleHull {
    fn push(&mut self, value: Option<f64>, length: usize) -> PineValue {
        self.full.push(value, length, false);
        let half = (length / 2).max(1);
        let smooth_length = (length as f64).sqrt().round().max(1.0) as usize;
        let difference = self.full.ready(length).then(|| {
            2.0 * self.full.weighted(length, length - half) - self.full.weighted(length, 0)
        });
        self.smooth.push(difference, smooth_length, false);
        if self.smooth.ready(smooth_length) { finite(self.smooth.weighted(smooth_length, 0)) }
        else { PineValue::Na }
    }
}
fn finite(value: f64) -> PineValue {
    if value.is_finite() { PineValue::Float(value) } else { PineValue::Na }
}
#[derive(Clone)]
struct OracleModel {
    case: String, wma: OracleWindow, hull: OracleHull, variance: OracleWindow,
    sma: OracleWindow, total: OracleWindow,
}
impl OracleModel {
    fn new(case: &str) -> Self {
        Self { case: case.into(), wma: OracleWindow::default(), hull: OracleHull::default(),
            variance: OracleWindow::default(), sma: OracleWindow::default(), total: OracleWindow::default() }
    }
    fn advance(&mut self, index: usize, price: f64) -> Vec<PineValue> {
        match self.case.as_str() {
            "cold_sum_warming" => {
                // Warm-up is incomplete until bar 2999. Every complete window
                // has 3000 positive samples >=5e307, so its sum must overflow;
                // a positive compensated reconstruction cannot make it finite.
                assert!(price.is_finite() && price >= 5.0e307);
                vec![PineValue::Na]
            }
            "variance_exact_zero" => {
                self.variance.push(Some(price), LENGTH, false);
                if !self.variance.ready(LENGTH) { vec![PineValue::Na; 4] }
                else {
                    let biased = self.variance.variance(LENGTH, true);
                    let unbiased = self.variance.variance(LENGTH, false);
                    vec![finite(biased), finite(unbiased), finite(biased.sqrt()), finite(unbiased.sqrt())]
                }
            }
            "same_callsite_loop" => {
                // Only the final same-callsite loop input survives for this bar.
                let value = Some(price + 0.75);
                self.total.push(value, LENGTH, true);
                self.sma.push(value, LENGTH, true);
                if !self.total.ready(LENGTH) { vec![PineValue::Na; 2] }
                else { vec![finite(self.total.sum), finite(self.sma.sum / LENGTH as f64)] }
            }
            _ => {
                let dynamic = self.case == "dynamic_na";
                let length = if dynamic && index % 211 >= 106 { 1536 } else { LENGTH };
                let value = if dynamic && matches!(index, 3100 | 3101) { None } else { Some(price) };
                self.wma.push(value, length, false);
                let wma = if self.wma.ready(length) { finite(self.wma.weighted(length, 0)) } else { PineValue::Na };
                let hma = self.hull.push(value, length);
                if self.case == "dyadic_wma_hma" { return vec![wma, hma]; }
                self.variance.push(value, length, false);
                let variance = if self.variance.ready(length) { finite(self.variance.variance(length, true)) } else { PineValue::Na };
                let mut result = vec![wma, hma, variance];
                if dynamic {
                    self.sma.push(value, length, true);
                    // math.sum skips an NA input, retaining the existing window.
                    if value.is_some() { self.total.push(value, length, true); }
                    result.push(if self.sma.ready(length) { finite(self.sma.sum / length as f64) } else { PineValue::Na });
                    result.push(if self.total.ready(length) { finite(self.total.sum) } else { PineValue::Na });
                }
                result
            }
        }
    }
}
fn append_expected(expected: &mut [Vec<PineValue>], next: Vec<PineValue>) {
    assert_eq!(expected.len(), next.len());
    for (plot, value) in expected.iter_mut().zip(next) { plot.push(value); }
}
fn oracle_seed(case: &str, prices: &[f64]) -> (OracleModel, Vec<Vec<PineValue>>) {
    let mut model = OracleModel::new(case);
    let mut expected: Vec<_> = (0..plot_count(case)).map(|_| Vec::with_capacity(prices.len() + 2)).collect();
    for (index, &price) in prices.iter().enumerate() { append_expected(&mut expected, model.advance(index, price)); }
    (model, expected)
}
fn oracle_forming(seed: &OracleModel, expected_seed: &[Vec<PineValue>], price: f64) -> Vec<Vec<PineValue>> {
    let mut model = seed.clone();
    let mut expected = expected_seed.to_vec();
    append_expected(&mut expected, model.advance(BARS, price));
    expected
}
fn check_result(result: &RuntimeResult, expected: &[Vec<PineValue>]) -> Result<Value, String> {
    if !result.diagnostics.is_empty() || result.plots.len() != expected.len() {
        return Err("fixture output shape or diagnostics diverged".into());
    }
    let mut digest = 0xcbf29ce484222325_u64;
    for (plot_index, (actual, expected)) in result.plots.iter().zip(expected).enumerate() {
        if actual.values.len() != expected.len() { return Err("incomplete plot history".into()); }
        for (index, (actual, expected)) in actual.values.iter().zip(expected).enumerate() {
            let matches = match (actual, expected) {
                (PineValue::Float(a), PineValue::Float(b)) => a.to_bits() == b.to_bits(),
                _ => actual == expected,
            };
            if !matches { return Err(format!("oracle mismatch plot={plot_index} bar={index}: actual={actual:?}, expected={expected:?}")); }
            let (tag, bits) = match actual { PineValue::Float(value) => (1_u8, value.to_bits()),
                PineValue::Int(value) => (2_u8, *value as u64), PineValue::Na => (0_u8, 0),
                _ => return Err("unexpected fixture value kind".into()) };
            for byte in std::iter::once(tag).chain(bits.to_le_bytes()) {
                digest = (digest ^ u64::from(byte)).wrapping_mul(0x100000001b3);
            }
        }
    }
    Ok(json!({"allValuesMatchOracle": true, "plotCount": expected.len(), "bars": expected[0].len(),
        "typedValueDigestFnv1a64": format!("{digest:016x}")}))
}
fn check_profile(profile: &RuntimeProfile, case: &str, bars: usize) -> Result<(), String> {
    if profile.bars != bars || profile.strategy_script_passes != 0
        || profile.plot_values != bars * plot_count(case) || profile.rolling_window_slots != window_count(case)
        || profile.array_slots != 0 || profile.matrix_slots != 0 {
        return Err(format!("bar/pass/plot/window/object profile diverged: {profile:?}"));
    }
    Ok(())
}
fn profile_json(profile: &RuntimeProfile) -> Result<Value, serde_json::Error> {
    let mut value: Value = serde_json::from_str(&public_runtime_profiled_result_json(&RuntimeResult::default(), profile))?;
    Ok(value["profile"].take())
}
fn save_payload(parts: &Path, name: &str, kind: &str, encoded: &str, files: &mut Vec<Value>) -> Result<(), Box<dyn std::error::Error>> {
    let path = parts.join(format!("{name}.json"));
    std::fs::write(&path, encoded)?;
    files.push(json!({"name": name, "kind": kind, "path": path.to_string_lossy(), "bytes": encoded.len()}));
    Ok(())
}
fn save_typed(parts: &Path, name: &str, result: &RuntimeResult, files: &mut Vec<Value>) -> Result<(), Box<dyn std::error::Error>> {
    let plots: Result<Vec<Vec<Value>>, String> = result.plots.iter().map(|plot| plot.values.iter().map(|value| match value {
        PineValue::Float(value) => Ok(json!(["float", format!("{:016x}", value.to_bits())])),
        PineValue::Int(value) => Ok(json!(["int", value.to_string()])), PineValue::Na => Ok(json!(["na"])),
        _ => Err("unexpected typed snapshot kind".into()),
    }).collect()).collect();
    let encoded = serde_json::to_string(&json!({"schema": "pine.window-probe.typed-plots.v1", "plots": plots?}))?;
    save_payload(parts, name, "typedPlotValues", &encoded, files)
}
